export function regionTargets(connection = "fibre") {
  return REGIONS.map((r) => {
    const target = pingTargetFor(r.id, connection);
    return {
      region: r,
      wiredTarget: target,
      playableCeiling: Math.round(target * 1.8),
      note: r.note
    };
  });
}
export function guessRegion(locale) {
  const l = (locale ?? "").toLowerCase();
  if (l.startsWith("en-gb") || l.endsWith("-ie"))
    return "uk";
  if (l.startsWith("ja") || l.startsWith("ko"))
    return "japan";
  if (l.startsWith("hi") || l.endsWith("-in") || l.endsWith("-pk") || l.endsWith("-bd"))
    return "india";
  if (l.endsWith("-au") || l.endsWith("-nz"))
    return "anz";
  if (l.endsWith("-sg") || l.endsWith("-my") || l.endsWith("-ph") || l.startsWith("th") || l.startsWith("vi") || l.startsWith("id"))
    return "sea";
  if (l.startsWith("ar") || l.startsWith("he") || l.startsWith("fa") || l.startsWith("tr"))
    return "mena";
  if (l.startsWith("pt-br") || l.startsWith("es-ar") || l.startsWith("es-mx") || l.startsWith("es-cl"))
    return "latam";
  if (l.startsWith("pl") || l.startsWith("cs") || l.startsWith("ru") || l.startsWith("uk-") || l.startsWith("hu") || l.startsWith("ro"))
    return "eu-central";
  if (l.startsWith("de") || l.startsWith("fr") || l.startsWith("nl") || l.startsWith("es") || l.startsWith("it") || l.startsWith("sv") || l.startsWith("da") || l.startsWith("no") || l.startsWith("fi"))
    return "eu-west";
  if (l.endsWith("-ca") || l.startsWith("en-us") || l.startsWith("en"))
    return "na-east";
  return "na-east";
}
